import json
import yaml
from typing import Dict, List, Any
from config import NEWS_SOURCES, KEYWORD_FILTERS, NEGATIVE_KEYWORDS, SCRAPING, BRIEF_CONFIG

def load_config() -> Dict[str, Any]:
    """Load and validate configuration."""
    return {
        'news_sources': NEWS_SOURCES,
        'keyword_filters': KEYWORD_FILTERS,
        'negative_keywords': NEGATIVE_KEYWORDS,
        'scraping': SCRAPING,
        'brief_config': BRIEF_CONFIG
    }

def get_active_telegram_channels() -> List[Dict[str, Any]]:
    """Get all enabled Telegram channels."""
    channels = []
    telegram_config = NEWS_SOURCES.get('telegram', {})

    if not telegram_config.get('enabled', False):
        return channels

    for category, channel_list in telegram_config.get('channels', {}).items():
        for channel in channel_list:
            if channel.get('enabled', True):
                channel['category'] = category
                channels.append(channel)

    return channels

def get_active_websites() -> List[Dict[str, Any]]:
    """Get all enabled websites."""
    websites_config = NEWS_SOURCES.get('websites', {})
    if not websites_config.get('enabled', False):
        return []

    return [site for site in websites_config.get('sources', []) 
            if site.get('enabled', True)]

def get_tier_keywords(tier: str) -> Dict[str, Any]:
    """Get keywords for a specific tier."""
    keywords = {}
    for category, tiers in KEYWORD_FILTERS.items():
        if tier in tiers:
            keywords[category] = tiers[tier]
    return keywords
